using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
internal sealed partial class ModernWorkspace {
 GoogleDriveClient googleClient;bool googleBusy,googleSheetsOnly;string googleQuery="",googleNext="",googleMessage="";CancellationTokenSource googleCancellation;readonly List<GoogleFilePin> googleResults=new List<GoogleFilePin>();
 GoogleDriveClient GoogleClient{get{if(googleClient==null)googleClient=new GoogleDriveClient(new GoogleVault(Path.Combine(Path.GetDirectoryName(Path.GetFullPath(store.Root)),"GoogleConnection")));return googleClient;}}
 void GooglePage(StackPanel root){GoogleSession account=null;GoogleClientConfig config=null;try{config=GoogleClient.Vault.Read<GoogleClientConfig>("client");account=GoogleClient.Vault.Read<GoogleSession>("session");}catch{googleMessage="La connexion locale est illisible sur ce compte Windows. Déconnectez ce PC puis reconnectez Google.";}var tools=new WrapPanel{Margin=new Thickness(0,0,0,12)};var configure=Btn("Importer la configuration Google",delegate{using(var picker=new System.Windows.Forms.OpenFileDialog{Title="Client OAuth Google · Application de bureau",Filter="Configuration Google JSON|*.json"})if(picker.ShowDialog()==System.Windows.Forms.DialogResult.OK)try{GoogleClient.Vault.ImportConfig(picker.FileName);googleResults.Clear();googleNext="";googleMessage="Configuration importée. Vous pouvez connecter votre compte Google.";Refresh();}catch(Exception ex){MessageBox.Show(ex.Message,"Configuration Google");}},false,true);configure.IsEnabled=!googleBusy;tools.Children.Add(configure);tools.Children.Add(Btn("Comment activer la connexion ?",delegate{GoogleSetupGuide();},false,true));root.Children.Add(tools);var status=new StackPanel();status.Children.Add(T(account==null?"Google Drive · Non connecté":"Connecté · "+(String.IsNullOrEmpty(account.email)?account.displayName:account.email),15));status.Children.Add(T("Retrouvez vos fichiers ici. Les PDF, images, textes et aperçus Docs/Sheets peuvent s’ouvrir directement ici. Les aperçus Docs/Sheets sont en lecture seule.",12,Muted,new Thickness(0,8,0,12)));var connections=new WrapPanel();if(account==null||!(account.scope??"").Contains("calendar.events")){var connect=Btn(account==null?"Connecter mon compte Google":"Autoriser Agenda et les documents",delegate{googleResults.Clear();googleNext="";GoogleOperation(async token=>{await GoogleClient.Connect(url=>Open(url),token);googleMessage="Compte Google connecté. Recherchez vos fichiers ou affichez les plus récents.";}, "Connexion dans votre navigateur…");},true);connect.IsEnabled=!googleBusy&&config!=null;connections.Children.Add(connect);if(config==null)status.Children.Add(T("La connexion nécessite le JSON d’un client OAuth « Application de bureau ». Les liens manuels sont déjà utilisables ci-dessous.",11,Muted,new Thickness(0,0,0,12)));}var disconnect=Btn("Déconnecter ce PC",delegate{GoogleOperation(async token=>{try{await GoogleClient.Disconnect(token);googleMessage="Connexion effacée sur ce PC. Les autres appareils conservent leur connexion.";}finally{googleResults.Clear();googleNext="";}}, "Déconnexion…");},false,true);disconnect.IsEnabled=!googleBusy;connections.Children.Add(disconnect);if(googleBusy)connections.Children.Add(Btn("Annuler",delegate{CancelGoogle();},false,true));status.Children.Add(connections);root.Children.Add(Card("Votre compte Google",status));if(!String.IsNullOrEmpty(googleMessage))root.Children.Add(T(googleMessage,12,AccentText,new Thickness(0,14,0,14)));
 var searchTools=new DockPanel{Margin=new Thickness(0,16,0,15)};var search=new TextBox{Text=googleQuery,MaxLength=200,ToolTip="Rechercher un nom dans Google Drive"};var sheets=new CheckBox{Content="Sheets uniquement",IsChecked=googleSheetsOnly,Margin=new Thickness(12,4,12,0)};var run=Btn("Rechercher / Actualiser",delegate{googleQuery=search.Text;googleSheetsOnly=sheets.IsChecked==true;FetchGoogle(false);},true);run.IsEnabled=account!=null&&!googleBusy;DockPanel.SetDock(run,Dock.Right);searchTools.Children.Add(run);DockPanel.SetDock(sheets,Dock.Right);searchTools.Children.Add(sheets);searchTools.Children.Add(search);search.KeyDown+=delegate(object sender,System.Windows.Input.KeyEventArgs e){if(e.Key==System.Windows.Input.Key.Enter&&account!=null&&!googleBusy){googleQuery=search.Text;googleSheetsOnly=sheets.IsChecked==true;FetchGoogle(false);e.Handled=true;}};root.Children.Add(searchTools);if(account!=null&&googleResults.Count==0&&!googleBusy)root.Children.Add(T("Lancez une recherche, ou laissez le champ vide pour afficher les fichiers récents.",12,Muted,new Thickness(0,0,0,15)));foreach(var file in googleResults)root.Children.Add(GoogleFileCard(file,true));if(!String.IsNullOrEmpty(googleNext)){var more=Btn("Charger la suite",delegate{FetchGoogle(true);});more.IsEnabled=!googleBusy;root.Children.Add(more);}var savedHeader=new DockPanel{Margin=new Thickness(0,24,0,15)};var add=Btn("+  Ajouter un lien Google",delegate{AddGoogleLink();},false,true);DockPanel.SetDock(add,Dock.Right);savedHeader.Children.Add(add);savedHeader.Children.Add(T("Mes liens Google enregistrés",18));root.Children.Add(savedHeader);if(store.Value.googlePins.Count==0)root.Children.Add(T("Ajoutez un lien Drive ou Sheets, ou épinglez un résultat. Les liens enregistrés restent disponibles sans connexion API.",12,Muted));foreach(var pin in store.Value.googlePins.ToList())root.Children.Add(GoogleFileCard(pin,false));}
 Border GoogleFileCard(GoogleFilePin file,bool remote){var body=new StackPanel();body.Children.Add(T(file.name,15));body.Children.Add(T(GoogleFiles.TypeName(file.mimeType),11,Muted,new Thickness(0,6,0,12)));var buttons=new WrapPanel();if(file.mimeType!="application/vnd.google-apps.folder")buttons.Children.Add(Btn("Dans l’application",delegate{OpenGoogleDocument(file);},true));buttons.Children.Add(Btn("Dans le navigateur",delegate{Open(file.url);},false,true));buttons.Children.Add(Btn(IsFavorite("google",file.id)?"★  Épinglé":"☆  Épingler",delegate{try{if(!IsFavorite("google",file.id))GoogleFiles.Remember(store.Value,file);ToggleFavorite("google",file.id,file.name);}catch(Exception ex){MessageBox.Show(ex.Message,"Lien Google");}},false,true));buttons.Children.Add(Btn("+  À un projet",delegate{AddGoogleToProject(file);},false,true));if(!remote)buttons.Children.Add(Btn("Retirer",delegate{store.Value.googlePins.RemoveAll(p=>p.id==file.id);store.Value.favorites.RemoveAll(f=>f.kind=="google"&&f.id==file.id);owner.Save();Refresh();},false,true));body.Children.Add(buttons);var card=Box(body,new Thickness(16));card.Margin=new Thickness(0,0,0,12);return card;}
 async void GoogleOperation(Func<CancellationToken,Task> operation,string message){if(googleBusy)return;googleBusy=true;googleCancellation=new CancellationTokenSource();googleMessage=message;Refresh();try{await operation(googleCancellation.Token);}catch(OperationCanceledException){googleMessage="Opération Google annulée ou délai dépassé.";}catch(Exception ex){googleMessage=ex.Message;}finally{googleBusy=false;if(googleCancellation!=null)googleCancellation.Dispose();googleCancellation=null;if(!owner.IsDisposed)Refresh();}}
 void FetchGoogle(bool more){string query=googleQuery;bool sheets=googleSheetsOnly;string next=more?googleNext:"";GoogleOperation(async token=>{var page=await GoogleClient.List(query,sheets,next,token);token.ThrowIfCancellationRequested();if(!more)googleResults.Clear();foreach(var file in page.files??new List<DriveRemoteFile>()){var pin=GoogleDriveClient.Pin(file);if(!googleResults.Any(p=>p.id==pin.id))googleResults.Add(pin);}googleNext=page.nextPageToken??"";googleMessage=googleResults.Count+" fichier(s) affiché(s)"+(page.incompleteSearch?" · Certains résultats peuvent manquer.":"");}, "Recherche dans Google Drive…");}
 internal void CancelGoogle(){if(googleCancellation!=null)googleCancellation.Cancel();}
 void AddGoogleLink(){StackPanel body,actions;var w=Dialog("Ajouter un lien Google",out body,out actions,490);var name=new TextBox{MaxLength=200};var url=new TextBox{MaxLength=2048};Field(body,"Nom du document ou du dossier",name);Field(body,"Lien Google Drive, Docs ou Sheets",url);var pin=new CheckBox{Content="Épingler dans mes favoris",IsChecked=true};body.Children.Add(pin);var error=T("",12,AccentText);body.Children.Add(error);actions.Children.Add(Btn("Annuler",delegate{w.DialogResult=false;},false,true));actions.Children.Add(Btn("Ajouter",delegate{try{var file=GoogleFiles.FromLink(name.Text.Trim(),url.Text.Trim());if(pin.IsChecked==true&&!IsFavorite("google",file.id)&&store.Value.favorites.Count>=200){error.Text="Limite : 200 favoris. Décochez l’épingle ou retirez un favori.";return;}GoogleFiles.Remember(store.Value,file);if(pin.IsChecked==true&&!IsFavorite("google",file.id))store.Value.favorites.Add(new Favorite{kind="google",id=file.id,label=file.name});if(owner.Save())w.DialogResult=true;}catch(Exception ex){error.Text=ex.Message;}},true));ShowWindow(w);Refresh();}
 void AddGoogleToProject(GoogleFilePin file){StackPanel body,actions;var w=Dialog("Lier au projet",out body,out actions,390);body.Children.Add(T(file.name,16,Ink,new Thickness(0,0,0,18)));var project=Combo(owner.AllProjects(),owner.AllProjects()[0]);Field(body,"Projet",project);actions.Children.Add(Btn("Annuler",delegate{w.DialogResult=false;},false,true));actions.Children.Add(Btn("Ajouter",delegate{try{GoogleFiles.Remember(store.Value,file);var space=ProjectData.Get(store.Value,Convert.ToString(project.SelectedItem));if(!space.links.Any(l=>l.Url==file.url))space.links.Add(new QuickLink{Name=file.name,Url=file.url});if(owner.Save())w.DialogResult=true;}catch(Exception ex){MessageBox.Show(ex.Message,"Lien Google");}},true));ShowWindow(w);Refresh();}
 void GoogleSetupGuide(){StackPanel body,actions;var w=Dialog("Activer Google Drive",out body,out actions,720);foreach(var step in new[]{"1. Dans Google Cloud Console, créez ou sélectionnez le projet de l’application.","2. Activez Google Drive API et Google Calendar API dans la bibliothèque des API.","3. Configurez Google Auth Platform : audience externe en test, puis ajoutez votre compte et celui de votre frère comme utilisateurs de test.","4. Dans Accès aux données, ajoutez l’autorisation drive.readonly, calendar.events et calendar.calendarlist.readonly (lecture des documents, gestion des événements et liste des agendas).","5. Créez un client OAuth de type Application de bureau et téléchargez son fichier JSON.","6. Revenez dans Google Drive > Importer la configuration Google, puis Connecter mon compte Google."})body.Children.Add(T(step,13,Ink,new Thickness(0,0,0,16)));body.Children.Add(T("Ce mode de connexion demande une configuration Google propre à l’application. Une diffusion publique peut nécessiter une validation par Google. Les mots de passe ne sont jamais saisis dans Mon espace. Les accès Google sont conservés chiffrés sur ce compte Windows et ne sont pas inclus dans les sauvegardes.",12,Muted,new Thickness(0,8,0,20)));body.Children.Add(Btn("Gérer les accès dans mon compte Google",delegate{Open("https://myaccount.google.com/connections");},false,true));body.Children.Add(Btn("Ouvrir Google Cloud Console",delegate{Open("https://console.cloud.google.com/");}));body.Children.Add(Btn("Documentation Google · application de bureau",delegate{Open("https://developers.google.com/identity/protocols/oauth2/native-app");},false,true));actions.Children.Add(Btn("Fermer",delegate{w.DialogResult=false;},true));ShowWindow(w);}
 StackPanel GooglePinButtons(bool compact){var body=new StackPanel();foreach(var file in store.Value.googlePins.Take(compact?2:4)){var item=file;var b=Btn(item.name,delegate{OpenGoogleDocument(item);},false,true);b.HorizontalContentAlignment=HorizontalAlignment.Left;body.Children.Add(b);}if(store.Value.googlePins.Count==0)body.Children.Add(Btn("Ajouter un lien Google",delegate{Go("Google Drive");},false,true));return body;}
 internal void PreviewGoogle(string path){var old=store.Value.googlePins.ToList();var pin=GoogleFiles.FromLink("Mon tableau de suivi","https://docs.google.com/spreadsheets/d/exemple_preview/edit");store.Value.googlePins.Add(pin);selected="Google Drive";googleMessage="Aperçu de l’interface · aucun compte Google connecté.";Refresh();Preview(path+"-google.png");previewPrefix=path;GoogleSetupGuide();previewPrefix=null;store.Value.googlePins=old;}
